style.css:
@-moz-document domain("discord.com") {
/* =========================
   CUSTOM DISCORD THEME
   MADE FOR YOUR IMAGE
========================= */

:root{
    --bg: url("https://i.imgur.com/0Z8FQwQ.png");

    --main-color: #8c84ff;
    --dark-bg: rgba(10,10,15,0.72);
    --panel-bg: rgba(20,20,28,0.45);
    --panel-border: rgba(255,255,255,0.06);

    --text: #ffffff;
    --blur: 18px;
    --radius: 18px;
}

/* ===== FONT ===== */
*{
    font-family: "Poppins", sans-serif !important;
}

/* ===== BACKGROUND ===== */
body,
.appMount-2yBXZl,
.bg-1QIAus,
.app-2CXKsg{
    background: transparent !important;
}

.appMount-2yBXZl::before{
    content:"";
    position:fixed;
    inset:0;

    background-image: var(--bg);
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    filter: brightness(0.38) blur(2px);

    transform: scale(1.03);

    z-index:-2;
}

/* ===== DARK OVERLAY ===== */
.appMount-2yBXZl::after{
    content:"";
    position:fixed;
    inset:0;

    background:
    linear-gradient(
        135deg,
        rgba(7,7,12,0.82),
        rgba(18,18,28,0.74)
    );

    z-index:-1;
}

/* ===== LEFT SERVER BAR ===== */
.guilds-2JjMmN{
    background: rgba(8,8,12,0.35) !important;
    backdrop-filter: blur(var(--blur));
    border-right: 1px solid var(--panel-border);
}

/* ===== CHANNEL SIDEBAR ===== */
.sidebar-1tnWFu{
    background: var(--panel-bg) !important;
    backdrop-filter: blur(var(--blur));
    border-right: 1px solid var(--panel-border);
}

/* ===== MAIN CHAT ===== */
.chat-2ZfjoI{
    background: transparent !important;
}

/* ===== MEMBER LIST ===== */
.members-3WRCEx{
    background: rgba(15,15,20,0.32) !important;
    backdrop-filter: blur(12px);
    border-left: 1px solid var(--panel-border);
}

/* ===== TOP BAR ===== */
.title-31SJ6t,
.container-ZMc96U{
    background: rgba(15,15,20,0.35) !important;
    backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--panel-border);
}

/* ===== MESSAGE AREA ===== */
.scrollableContainer-15eg7h{
    background: rgba(20,20,30,0.42) !important;
    border: 1px solid rgba(255,255,255,0.05);
    border-radius: 16px;
    backdrop-filter: blur(10px);
}

/* ===== USER PANEL ===== */
.panels-3wFtMD{
    background: rgba(15,15,20,0.45) !important;
    backdrop-filter: blur(14px);
    border-top: 1px solid var(--panel-border);
}

/* ===== SETTINGS PAGE ===== */
.standardSidebarView-E9Pc3j{
    background: transparent !important;
}

.contentRegion-3HkfJJ{
    background: rgba(15,15,20,0.35) !important;
    backdrop-filter: blur(12px);
}

/* ===== POPUPS ===== */
.layer-86YKbF,
.root-1CAIjD{
    background: rgba(15,15,25,0.62) !important;
    backdrop-filter: blur(20px);
    border-radius: 22px;
}

/* ===== PROFILE POPUP ===== */
.userPopoutOuter-3AVBmJ{
    background: rgba(18,18,28,0.62) !important;
    backdrop-filter: blur(22px);
    border: 1px solid rgba(255,255,255,0.06);
}

/* ===== BUTTONS ===== */
.button-f2h6uQ{
    border-radius: 14px !important;
}

/* ===== SERVER ICONS ===== */
.wrapper-28eC3z foreignObject{
    border-radius: 18px !important;
    transition: 0.25s ease;
}

.wrapper-28eC3z:hover foreignObject{
    transform: scale(1.08);
}

/* ===== SELECTED CHANNEL ===== */
.modeSelected-3DmyhH .link-39sEB3{
    background: rgba(140,132,255,0.22) !important;
    border: 1px solid rgba(140,132,255,0.22);
    backdrop-filter: blur(8px);
}

/* ===== HOVER ===== */
.link-39sEB3:hover{
    background: rgba(255,255,255,0.05) !important;
}

/* ===== AVATAR GLOW ===== */
.avatar-2e8lTP,
.replyAvatar-sHd2sU{
    box-shadow:
    0 0 15px rgba(140,132,255,0.28),
    0 0 30px rgba(140,132,255,0.12);
}

/* ===== TEXT ===== */
h1,h2,h3,h4,h5,h6,
span,
div{
    color: var(--text);
}

/* ===== SCROLLBAR ===== */
::-webkit-scrollbar{
    width:6px;
}

::-webkit-scrollbar-thumb{
    background: rgba(255,255,255,0.18);
    border-radius:20px;
}

/* ===== SMOOTH ===== */
*{
    transition:
    background 0.2s ease,
    border 0.2s ease,
    transform 0.2s ease;
}
}
